  if(conds.length)html+='<p class="b-explain-conds" aria-label="Bedingungen">'+conds.map(([k,n])=>'<span class="b-cond '+STATE_ICON[k][2]+'"><i aria-hidden="true">'+STATE_ICON[k][0]+'</i> '+n+' '+(lkPluriel(n)?'Bedingungen '+STATE_ICON[k][3]:'Bedingung '+STATE_ICON[k][1])+'</span>').join('')+'</p>';
