  html+='<li><h5>Was die Antwort entscheidet</h5>'+(e.drivers.length?'<ul class="b-explain-list">'+e.drivers.map(d=>'<li><span><b>'+esc(d.label)+'</b> — '+esc(d.text)+'</span></li>').join('')+'</ul>':'<p>Noch nichts berechenbar: Ergänze die Zahlen.</p>')+(e.tradeoffs&&e.tradeoffs.length?'<p>'+esc(e.tradeoffs.join(' · '))+'</p>':'')+'</li>';
