 function hypothesesBlock(){const an=state().analysis;return '<details class="calc-optional b-hypotheses b-expert" id="calc-hypotheses"><summary>Meine Annahmen: Sprit, Wartung, Munition, Fehlversuche</summary><p class="calc-note"><b>Geltungsbereich:</b> Diese Annahmen zählen in den acht Berechnungen. Der Businessplan hat eigene Felder; er übernimmt nur die simulierte Munition, die zu den Kosten jedes Missionsversuchs addiert wird. Keine dieser Mechaniken ist in GTA VI bestätigt: Nichts wird ohne deine Wahl gezählt, und eine gewählte Zahl bleibt überall als „Simulation“ markiert, auch in deinen gespeicherten Berechnungen. Wenn du die Kosten pro Session eines Kaufs selbst einträgst, kommt die Simulation nicht dazu.</p>'+SIMS.map(([k,label,fields])=>'<fieldset class="b-sim-item"><legend>'+check('analysis.simulations.'+k,label,an.simulations[k])+'</legend><div class="calc-fields" data-sim-fields="'+k+'" '+(an.simulations[k]?'':'hidden')+'>'+fields.map(([f,l])=>field('analysis.sim.'+k+'.'+f,l,an.sim[k][f],{id:'sim-'+k+'-'+f,max:k==='echec'?10:1e12,integer:k==='echec'})).join('')+'</div></fieldset>').join('')+'<p class="calc-note">Sprit: Strecke × Verbrauch ÷ 100 × Literpreis = Kosten pro Session.</p></details>';}
 let plan=null;
