 $('panel-purchase').querySelector('.calc-card').insertAdjacentHTML('beforeend','<div class="b-purchase-links">'+btn('Lohnt es sich?','data-b-roi-current="1"')+btn('Zu „Was zuerst kaufen?“ hinzufügen','data-b-order-current="1"')+'</div>');
 document.querySelectorAll('.b-expert input[data-number],.calc-advanced input[data-number]').forEach(el=>{const path=el.dataset.field;if(!path)return;let ref=api.initial;for(const k of path.split('.'))ref=ref?.[k];if(path.startsWith('assets.')&&ref===undefined)ref=path.endsWith('extras')||path.endsWith('fees')||path.endsWith('boostHourly')?0:null;if(ref===undefined)return;el.closest('.calc-field').insertAdjacentHTML('beforeend','<small>Standardwert: '+esc(ref===null?'unbekannt':nf.format(ref))+'</small><button type="button" class="calc-text-button" data-b-default="'+esc(path)+'" data-b-default-value="'+esc(ref===null?'null':ref)+'">Diesen Wert wiederherstellen</button>');});
 mode();
