    const next=v==='unknown-gain'?{title:'Dein nächster Schritt',text:'Schreib, wie viel dir der Kauf pro Stunde zusätzlich einbringt, auch geschätzt: Die Antwort rechnet sich von selbst.'}:v==='even'?{title:'Dein nächster Schritt',text:c.investment===0?'Nimm ihn nur, wenn er dir anders nützt: Mit diesen Zahlen ändert er nichts an deinem Geld.':'Kauf ihn nur, wenn du ihn länger nutzt als '+hours(c.breakEvenHours)+': Darunter bleibt dir nichts zusätzlich.'}:v==='never'?{title:'Dein nächster Schritt',text:'Behalte dein Geld oder prüfe deine Zahlen: Was der Kauf einbringt, muss zu dem dazukommen, was du schon verdient hast, nach Abzug der Kosten.'}:v==='wait'?{title:'Dein nächster Schritt',text:'Spiel noch '+(t.waitHours!==null?hours(t.waitHours):'ein bisschen')+', dann schau wieder rein: Der Plan sagt dir, wann du es kaufen kannst.',button:btn('In meinen Businessplan übernehmen','data-b-roi-to-plan="1"')}:v==='buy'?{title:'Dein nächster Schritt',text:c.investment===0?'Nimm ihn: Jede Stunde, in der du ihn nutzt, bringt dir '+money(c.marginalHourly)+' mehr.':'Kauf es und nutze es mindestens '+hours(c.breakEvenHours)+' – ab dann bleiben dir pro Stunde '+money(c.marginalHourly)+' mehr.',button:btn('In meinen Businessplan übernehmen','data-b-roi-to-plan="1"')}:v==='unknown-horizon'?{title:'Dein nächster Schritt',text:'Gib ein, wie lange du es nutzen willst.',button:btn('Nutzungsdauer eintragen','data-b-focus="f-roi-hours"')}:{title:'Dein nächster Schritt',text:'Warte oder such einen Kauf, der mindestens '+money(t.extraHourlyForHorizon)+' pro Stunde einbringt: Damit ist er wieder eingespielt in '+hours(H)+'.'};
