  if(s.roi.compareKey){const alt=lookup(s.roi.compareKey),other=B.decision(s,sourceActivities,s.roi.compareKey);html+='<h4>Zwei Wünsche, ein Budget</h4>';if(d.valid&&other.valid)html+=table([['',a.name,alt.name],['Gesamtpreis',money(d.investment),money(other.investment)],['Dir fehlen',money(d.shortfall),money(other.shortfall)],['Bleibt danach, ohne Rücklage',d.shortfall?'Nicht genug':money(d.remaining),other.shortfall?'Nicht genug':money(other.remaining)],['Spielzeit, um den Preis wieder reinzuholen',hours(d.recoveryHours),hours(other.recoveryHours)]],'Preis und verbleibendes Geld · was wichtiger ist, entscheidest du',true);else html+=warning(other.reason||d.reason);}
  html+='<details><summary>Wie wird das berechnet?</summary><p class="calc-note">Was dir bleibt = Geld, das du hast − Rücklage − Preis − Optionen − Kosten. Die Zeit, bis du dein Geld zurückhast, wird mit dem berechnet, was du schon verdienst. Das Wiedereinspielen wird nur mit dem berechnet, was dir der Kauf ZUSÄTZLICH zu deinen bisherigen Einnahmen bringt: Wir vergleichen die Lage mit und ohne Kauf über dieselbe Spielzeit. Einen Preis, den die Seite nicht kennt, trägst du selbst ein.</p></details>'+btn('Zu „Was zuerst kaufen?“ hinzufügen','data-b-order-roi="1"');
