  html+='<div class="c-detail">'+table([['',...r.items.map(it=>it.name)],['Gesamtpreis',...r.items.map(it=>it.known?money(it.total):'einzutragen')],['Laufende Kosten',...r.items.map(it=>U(it.name))],['Kosten über '+(sessions?sessions+' Sessions':'die Dauer (Nutzungsstunden im Modus Experte eintragen)'),...r.items.map(it=>T(it.name))],['Passt zu deinem Bedarf',...r.items.map(it=>N(it.name))],['Kann ich es kaufen?',...r.items.map(it=>!it.known?'—':it.affordable?'Ja':'Dir fehlen '+money(it.shortfall))],['Wann?',...r.items.map(it=>it.known?when(it):'—')],['Wunsch',...r.items.map(it=>it.known?envie(it.utility):'—')],['Wunsch pro 100.000 $',...r.items.map(it=>it.valueScore===null?'—':nf.format(Math.round(it.valueScore*100)/100))],['Zeit, um den Preis wieder reinzuholen',...r.items.map(it=>it.recoveryHours===null||it.recoveryHours===undefined?'—':hours(it.recoveryHours))],['Bringt es Geld ein?',...r.items.map(it=>it.paybackHours===null?'Nein (oder nicht eingetragen)':'Wieder eingespielt nach '+hours(it.paybackHours))],/* v7.59 (check ultime, D-04) : « Je m’en sers pendant (heures de jeu) » (compare.hours) ne changeait rien à l’écran ; ce qu’il laisse après ce temps, prix enlevé, est maintenant montré pour les achats qui rapportent. */['Nach '+hours(s.compare.hours)+' Spielzeit, nach Abzug des Preises',...r.items.map(it=>it.gainOverHorizon===null||it.gainOverHorizon===undefined?'—':(it.gainOverHorizon>=0?'+':'−')+money(Math.abs(it.gainOverHorizon)))]],'Alle Käufe nebeneinander · gleiche Startzahlen',true)+'</div>';
